toad_implementation.code_blueprint:
canvas {
  size: 960px 580px;
  fill: #080C14;
  font-family: "Inter, sans-serif";
}

>trustBlue = #0066FF;
>gainGreen = #00D084;
>cardBg = #101622;
>cardBorder = #1C2638;
>textMuted = #64748B;
>textWhite = #F8FAFC;

rect #headerBar {
  at: top left of canvas offset 32px 32px;
  size: 896px 40px;
  fill: none;
}

text #dashTitle {
  at: left of #headerBar;
  content: "GLOBAL PORTFOLIO RISK OVERVIEW";
  font-size: 15px;
  font-weight: 700;
  color: >textWhite;
}

rect #heroCard {
  at: below #headerBar offset 20px;
  size: 580px 200px;
  fill: >cardBg;
  stroke: >cardBorder;
  stroke-width: 1px;
  radius: 8px;
}

text #totalAumLabel {
  at: top left of #heroCard offset 24px 20px;
  content: "TOTAL ASSETS UNDER MANAGEMENT";
  font-size: 11px;
  font-weight: 600;
  color: >textMuted;
}

text #totalAumValue {
  at: below #totalAumLabel offset 12px;
  content: "€ 428,940,120.00";
  font-size: 36px;
  font-weight: 700;
  color: >textWhite;
}

rect #deltaBadge {
  at: below #totalAumValue offset 16px;
  size: 110px 26px;
  fill: alpha(>gainGreen, 0.15);
  radius: 4px;
}

text #deltaText {
  at: center of #deltaBadge;
  content: "▲ + 3.84% 24H";
  font-size: 11px;
  font-weight: 700;
  color: >gainGreen;
}

rect #sideCard {
  at: right of #heroCard offset 24px;
  size: 292px 200px;
  fill: >cardBg;
  stroke: >cardBorder;
  stroke-width: 1px;
  radius: 8px;
}

text #liquidityLabel {
  at: top left of #sideCard offset 20px 20px;
  content: "LIQUIDITY RATIO";
  font-size: 11px;
  font-weight: 600;
  color: >textMuted;
}

text #liquidityValue {
  at: below #liquidityLabel offset 12px;
  content: "94.2 %";
  font-size: 32px;
  font-weight: 700;
  color: >trustBlue;
}
